/* Muuzee Artist Data — shared source of truth */
(() => {
  "use strict";

  const LEGACY_FEATURED = [{"name": "Pablo Picasso", "img": "data:image/png;base64,", "position": "center 24%"}, {"name": "Yayoi Kusama", "img": "data:image/png;base64,", "position": "center 34%"}, {"name": "Claude Monet", "img": "data:image/png;base64,", "position": "center 25%"}, {"name": "Pierre-Auguste Renoir", "img": "data:image/png;base64,", "position": "center 24%"}, {"name": "Edgar Degas", "img": "data:image/png;base64,", "position": "center 23%"}, {"name": "Camille Pissarro", "img": "data:image/png;base64,", "position": "center 24%"}];
  const CATALOG = [
  {name:"草間彌生",category:["現代美術"],origin:"日本人",country:"日本",eras:["20世紀後半","2000年代以降"],image:"./assets/images/exhibitions/exhibition-01.jpg",aliases:["草間彌生","草間弥生","Yayoi Kusama","Kusama"]},
  {name:"奈良美智",category:["現代美術"],origin:"日本人",country:"日本",eras:["20世紀後半","2000年代以降"],image:"./assets/images/exhibitions/exhibition-02.jpg",aliases:["奈良美智","Yoshitomo Nara","Nara"]},
  {name:"村上隆",category:["現代美術","ポップアート"],origin:"日本人",country:"日本",eras:["20世紀後半","2000年代以降"],image:"./assets/images/exhibitions/exhibition-03.jpg",aliases:["村上隆","Takashi Murakami","Murakami"]},
  {name:"杉本博司",category:["現代美術"],origin:"日本人",country:"日本",eras:["20世紀後半","2000年代以降"],image:"./assets/images/exhibitions/exhibition-04.jpg",aliases:["杉本博司","Hiroshi Sugimoto","Sugimoto"]},
  {name:"塩田千春",category:["現代美術"],origin:"日本人",country:"日本",eras:["20世紀後半","2000年代以降"],image:"./assets/images/exhibitions/exhibition-05.jpg",aliases:["塩田千春","Chiharu Shiota","Shiota"]},
  {name:"横尾忠則",category:["現代美術","ポップアート"],origin:"日本人",country:"日本",eras:["20世紀後半","2000年代以降"],image:"./assets/images/exhibitions/exhibition-06.jpg",aliases:["横尾忠則","Tadanori Yokoo","Yokoo"]},
  {name:"葛飾北斎",category:["日本美術"],origin:"日本人",country:"日本",eras:["19世紀以前","19世紀"],image:"./assets/images/exhibitions/exhibition-07.jpg",aliases:["葛飾北斎","Katsushika Hokusai","Hokusai"]},
  {name:"アンディ・ウォーホル",category:["ポップアート","現代美術"],origin:"外国人",country:"アメリカ",eras:["20世紀後半"],image:"./assets/images/exhibitions/exhibition-08.jpg",aliases:["アンディ・ウォーホル","Andy Warhol","Warhol"]},
  {name:"デイヴィッド・ホックニー",category:["現代美術","ポップアート"],origin:"外国人",country:"イギリス",eras:["20世紀後半","2000年代以降"],image:"./assets/images/exhibitions/exhibition-09.jpg",aliases:["デイヴィッド・ホックニー","David Hockney","Hockney"]},
  {name:"バンクシー",category:["現代美術"],origin:"外国人",country:"イギリス",eras:["20世紀後半","2000年代以降"],image:"./assets/images/exhibitions/exhibition-01.jpg",aliases:["バンクシー","Banksy"]},
  {name:"ゲルハルト・リヒター",category:["現代美術"],origin:"外国人",country:"ドイツ",eras:["20世紀後半","2000年代以降"],image:"./assets/images/exhibitions/exhibition-02.jpg",aliases:["ゲルハルト・リヒター","Gerhard Richter","Richter"]},
  {name:"クロード・モネ",category:["印象派"],origin:"外国人",country:"フランス",eras:["19世紀","20世紀前半"],image:"./assets/images/exhibitions/exhibition-03.jpg",aliases:["クロード・モネ","モネ","Claude Monet","Monet"]},
  {name:"エドガー・ドガ",category:["印象派"],origin:"外国人",country:"フランス",eras:["19世紀","20世紀前半"],image:"./assets/images/exhibitions/exhibition-04.jpg",aliases:["エドガー・ドガ","Edgar Degas","Degas"]},
  {name:"ピエール＝オーギュスト・ルノワール",category:["印象派"],origin:"外国人",country:"フランス",eras:["19世紀","20世紀前半"],image:"./assets/images/exhibitions/exhibition-05.jpg",aliases:["ピエール＝オーギュスト・ルノワール","ルノワール","Pierre-Auguste Renoir","Renoir"]},
  {name:"フィンセント・ファン・ゴッホ",category:["ポスト印象派"],origin:"外国人",country:"オランダ",eras:["19世紀"],image:"./assets/images/exhibitions/exhibition-06.jpg",aliases:["フィンセント・ファン・ゴッホ","ゴッホ","Vincent van Gogh","Van Gogh","Gogh"]},
  {name:"ポール・セザンヌ",category:["ポスト印象派"],origin:"外国人",country:"フランス",eras:["19世紀","20世紀前半"],image:"./assets/images/exhibitions/exhibition-07.jpg",aliases:["ポール・セザンヌ","セザンヌ","Paul Cézanne","Paul Cezanne","Cézanne","Cezanne"]},
  {name:"パブロ・ピカソ",category:["近代美術"],origin:"外国人",country:"スペイン",eras:["20世紀前半","20世紀後半"],image:"./assets/images/exhibitions/exhibition-08.jpg",aliases:["パブロ・ピカソ","Pablo Picasso","Picasso"]},
  {name:"フリーダ・カーロ",category:["近代美術"],origin:"外国人",country:"メキシコ",eras:["20世紀前半"],image:"./assets/images/exhibitions/exhibition-09.jpg",aliases:["フリーダ・カーロ","Frida Kahlo","Kahlo"]}
];

  const normalize = value => String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g,"")
    .toLowerCase()
    .replace(/[\s・＝=._'’"\-–—]/g,"");

  const findLegacy = artist => {
    const aliases = [artist.name,...(artist.aliases || [])].map(normalize).filter(Boolean);
    return LEGACY_FEATURED.find(item => {
      const legacyName = normalize(item.name);
      return aliases.some(alias => legacyName === alias || legacyName.includes(alias) || alias.includes(legacyName));
    });
  };

  const catalog = CATALOG.map(artist => {
    const legacy = findLegacy(artist);
    const image = legacy?.img || legacy?.image || artist.image;
    return {
      ...artist,
      image,
      img:image,
      position:legacy?.position || "center",
      featured:Boolean(legacy)
    };
  });

  window.MuuzeeArtistCatalog = catalog;
})();

/* exhibition-sample-artist:start */
(() => {
  "use strict";
  const catalog = window.MuuzeeArtistCatalog;
  if(!Array.isArray(catalog) || catalog.some(artist => artist.name === "庄島歩音")) return;

  catalog.push({
    name:"庄島歩音",
    category:["イラストレーション","フォークアート"],
    origin:"日本人",
    country:"日本",
    place:"日本",
    eras:["2000年代以降"],
    image:'data:image/jpeg;base64,',
    img:'data:image/jpeg;base64,',
    position:"center",
    featured:false,
    aliases:["庄島歩音"]
  });
})();
/* exhibition-sample-artist:end */

/* order656-relation-artists:start */
(() => {
  "use strict";

  const catalog = window.MuuzeeArtistCatalog;
  if(!Array.isArray(catalog)) return;

  const fixtures = [
    {id:"kumiko-koyama",name:"小山久美子",category:["絵画"],tagIds:["painting"]},
    {id:"takehisa-yumeji",name:"竹久夢二",category:["日本画"],tagIds:["japanese-painting"]},
    {id:"zak-prekop",name:"Zak Prekop",category:["現代美術","絵画"],tagIds:["contemporary","painting"]},
    {id:"nobuko-watahiki",name:"綿引展子",category:["絵画"],tagIds:["painting"]},
    {id:"taichi-nakamura",name:"中村太一",category:["絵画"],tagIds:["painting"]}
  ];

  const existingIds = new Set(catalog.map(artist => artist.id).filter(Boolean));
  fixtures.forEach(fixture => {
    if(existingIds.has(fixture.id)) return;
    catalog.push({
      ...fixture,
      country:"",
      place:"情報確認中",
      eras:[],
      image:"./assets/images/placeholders/artist-neutral.svg",
      img:"./assets/images/placeholders/artist-neutral.svg",
      position:"center",
      featured:false,
      aliases:[fixture.name]
    });
  });
})();
/* order656-relation-artists:end */
